#include "NamedGearCatalogue.hpp"
namespace elysium::content { bool NamedGearCatalogue::add(NamedGearRow r,std::string&w){if(!r.id||!r.profile||!r.element){w="missing identity/profile/element";return false;}if(r.acquisitionRefs.empty()){w="missing acquisition source";return false;}if(!rows_.emplace(r.id,std::move(r)).second){w="duplicate named gear";return false;}return true;} bool NamedGearCatalogue::validate(std::string&w)const{for(auto&[id,r]:rows_){if(r.tier>64){w="invalid tier";return false;}if(r.setId&&!r.setBonusRefs.size()){w="set without bonus";return false;}}return true;} std::uint32_t NamedGearCatalogue::activeSetBonuses(ContentId setId,const std::vector<ContentId>& eq)const{std::uint32_t pieces=0,bonuses=0;for(auto id:eq){auto i=rows_.find(id);if(i!=rows_.end()&&i->second.setId==setId)++pieces;}for(auto&[_,r]:rows_)if(r.setId==setId)bonuses=std::max<std::uint32_t>(bonuses,std::min<std::uint32_t>(pieces,r.setBonusRefs.size()));return bonuses;} std::optional<NamedGearRow> NamedGearCatalogue::get(ContentId id)const{auto i=rows_.find(id);if(i==rows_.end())return std::nullopt;return i->second;} }